const updateAgentToolCallResult = `-- name: UpdateAgentToolCallResult :one
UPDATE ai_agent_tool_calls SET
    result         = $1,
    status         = $2,
    error_message  = $3,
    latency_ms     = $4,
    hitl_review_id = $5
WHERE id = $6 AND tenant_id = $7
RETURNING id, tenant_id, session_id, tool_name, arguments, result, status, error_message, latency_ms, rbac_checked, privacy_checked, hitl_review_id, created_at
`

type UpdateAgentToolCallResultParams struct {
	Result       []byte      `json:"result"`
	Status       string      `json:"status"`
	ErrorMessage *string     `json:"error_message"`
	LatencyMs    *int32      `json:"latency_ms"`
	HitlReviewID pgtype.UUID `json:"hitl_review_id"`
	ID           pgtype.UUID `json:"id"`
	TenantID     pgtype.UUID `json:"tenant_id"`
}

// Record the outcome of a tool call. result is nullable jsonb (an error
// call may have no result payload). hitl_review_id is set only when the
// call was queued for HITL (status = 'hitl_queued').
func (q *Queries) UpdateAgentToolCallResult(ctx context.Context, arg UpdateAgentToolCallResultParams) (AiAgentToolCall, error) {
	row := q.db.QueryRow(ctx, updateAgentToolCallResult,
		arg.Result,
		arg.Status,
		arg.ErrorMessage,
		arg.LatencyMs,
		arg.HitlReviewID,
		arg.ID,
		arg.TenantID,
	)
	var i AiAgentToolCall
	err := row.Scan(
		&i.ID,
		&i.TenantID,
		&i.SessionID,
		&i.ToolName,
		&i.Arguments,
		&i.Result,
		&i.Status,
		&i.ErrorMessage,
		&i.LatencyMs,
		&i.RbacChecked,
		&i.PrivacyChecked,
		&i.HitlReviewID,
		&i.CreatedAt,
	)
	return i, err
}
